80	// The invite rides in the fragment, which is never sent to the host.
81	// It is cleared before any request so it does not stay in the address bar.
82	function takeInvite() {
83	  const params = new URLSearchParams(location.hash.slice(1));
84	  const code = params.get("code");
85	  const key = params.get("key");
86	  const id = params.get("id");
87	  if (!code || !key || !id) return null;
88	  history.replaceState(null, "", "/");
89	  return { code, key, id };
90	}
91	
92	async function start() {
93	  const invite = takeInvite();
94	  const stored = readStored();
95	  let info;
96	  try {
97	    const res = await call("GET", "info");
98	    info = res.json && res.json.body;
99	  } catch {
100	    notice("Cannot reach the host.");
101	    return;
102	  }
103	  if (!info) {
104	    notice("The host did not answer.");
105	    return;
106	  }
107	  state.info = info;
108	  $("host").textContent = info.server_name || "Switchboard";
109	  if (stored && stored.server_id === info.server_id && stored.spki_sha256 !== info.spki_sha256) {
110	    notice("This host's identity changed. Pair again.");
111	    return;
112	  }
113	  if (invite) {
114	    if (invite.key !== info.spki_sha256) {
115	      notice("This is not the host whose code was scanned.");
116	      return;
117	    }
118	    const res = await call("POST", "pair", {
119	      code: invite.code,
120	      spki_sha256: info.spki_sha256,
121	      device_name: deviceName(),
122	      transport: "cookie",
123	    });
124	    if (res.status !== 200) {
125	      const msg = res.json && res.json.error ? res.json.error.message : "pairing failed";
126	      notice("Pairing failed: " + msg + ".");
127	      return;
128	    }
129	    state.scope = res.json.body.scope;
130	    localStorage.setItem(
131	      STORE,
132	      JSON.stringify({ server_id: info.server_id, spki_sha256: info.spki_sha256, scope: state.scope }),
133	    );
134	  } else if (stored) {
135	    state.scope = stored.scope || "read";
136	  }
137	  const waiting = await call("GET", "waiting");
138	  if (waiting.status === 401) {
139	    notice(
140	      readStored()
141	        ? "This device was revoked. Pair again."
142	        : "Not paired. Open Remote devices on the Mac and scan the code.",
143	    );
144	    return;
145	  }
146	  if (waiting.status !== 200) {
147	    notice("The host refused: " + waiting.status + ".");
148	    return;
149	  }
150	  // A cookie the browser did not keep shows up here: the first
151	  // authenticated call after pairing is refused.
152	  openSocket();
153	  await refresh();
154	  schedule();
155	}
156	
157	async function refresh() {
158	  if (state.refreshing) return;
159	  state.refreshing = true;
160	  try {
161	    const projects = await call("GET", "projects");
162	    if (projects.status === 401) {
163	      notice("This device was revoked. Pair again.");
164	      return;
165	    }
166	    if (projects.status !== 200) return;
167	    state.rev.projects = projects.json.revision;
168	    state.projects = projects.json.body.projects;
169	    const lists = await Promise.all(
170	      state.projects.map((p) => call("GET", "projects/" + p.id + "/sessions")),
171	    );
172	    state.sessions = [];
173	    lists.forEach((res, i) => {
174	      if (res.status !== 200) return;
175	      for (const s of res.json.body.sessions) {
176	        state.sessions.push({ ...s, project_name: state.projects[i].name });
177	      }
178	    });
179	    if (state.open) await loadContent();
180	    render();
181	  } finally {
182	    state.refreshing = false;
183	  }
184	}
185	
186	async function loadContent() {
187	  const s = state.sessions.find((x) => x.id === state.open);
188	  if (!s) return;
189	  const leaf = s.kind === "claude" ? "last-response" : "screen";
190	  const res = await call("GET", "sessions/" + s.id + "/" + leaf);
191	  if (res.status === 200) state.text = res.json.body.text || "";
192	}
193	
194	function render() {
195	  $("status").textContent = (state.live ? "live" : "polling") + " · " + state.scope;
196	  if (state.open) {
197	    renderSession();
198	    return;
199	  }
200	  const rank = (s) => (s.waiting ? 0 : 1);
201	  const groups = state.projects.map((p) => ({
202	    project: p,
203	    sessions: state.sessions.filter((s) => s.project === p.id).sort((a, b) => rank(a) - rank(b)),
204	  }));
205	  groups.sort((a, b) => {
206	    const wa = a.sessions.some((s) => s.waiting) ? 0 : 1;
207	    const wb = b.sessions.some((s) => s.waiting) ? 0 : 1;
208	    return wa - wb;
209	  });
210	  const kids = [];
211	  for (const g of groups) {
212	    if (g.sessions.length === 0) continue;
213	    kids.push(el("h2", {}, g.project.name));
214	    for (const s of g.sessions) {
215	      const line = [s.kind, s.card, s.waiting && s.waiting_reason ? s.waiting_reason : ""]
216	        .filter(Boolean)
217	        .join(" · ");
218	      kids.push(
219	        el(
220	          "button",
221	          { class: "row" + (s.waiting ? " waiting" : ""), onclick: () => openSession(s.id) },
222	          el("div", { class: "name" }, s.name),
223	          el("div", { class: "meta" }, line),
224	        ),
225	      );
226	    }
227	  }
228	  if (kids.length === 0) kids.push(el("div", { class: "notice" }, "No sessions."));
229	  main.replaceChildren(...kids);
230	}
231	
232	function renderSession() {
233	  const s = state.sessions.find((x) => x.id === state.open);
234	  if (!s) {
235	    state.open = null;
236	    render();
237	    return;
238	  }
239	  const kids = [
240	    el("button", { class: "act", onclick: closeSession }, "Back"),
241	    el("h2", {}, s.name),
242	    el("div", { class: "meta" }, [s.kind, s.card, s.waiting_reason || ""].filter(Boolean).join(" · ")),
243	    el("pre", {}, state.text),
244	  ];
245	  if (state.scope === "control") {
246	    // Rebuilding the page on each event must not eat what is being typed.
247	    const prior = document.getElementById("reply");
248	    const box = el("textarea", { id: "reply", placeholder: "Reply to the session" });
249	    if (prior) box.value = prior.value;
250	    kids.push(box, el("button", { class: "act", onclick: () => send(s.id, box) }, "Send"));
251	    kids.push(el("div", { class: "meta", id: "sent" }));
252	  }
253	  main.replaceChildren(...kids);
254	}
255	
256	async function openSession(id) {
257	  state.open = id;
258	  state.text = "";
259	  await loadContent();
260	  watch("watch");
261	  render();
262	}
263	
264	function closeSession() {
265	  watch("unwatch");
266	  state.open = null;
267	  render();
268	}
269	
270	function contentKind() {
271	  const s = state.sessions.find((x) => x.id === state.open);
272	  return s && s.kind === "claude" ? "conversation" : "screen";
273	}
274	
275	function watch(type) {
276	  if (!state.open || !state.socket || state.socket.readyState !== WebSocket.OPEN) return;
277	  state.socket.send(JSON.stringify({ type, resource: { kind: contentKind(), id: state.open } }));
278	}
279	
280	async function send(id, box) {
281	  const text = box.value.trim();
282	  if (!text) return;
283	  const op = crypto.randomUUID();
284	  const res = await call("POST", "sessions/" + id + "/send", { op, text });
285	  const out = $("sent");
286	  if (res.status === 403) {
287	    state.scope = "read";
288	    render();
289	    notice("This device is read-only now.");
290	    return;
291	  }
292	  if (res.status === 200) {
293	    box.value = "";
294	    if (out) out.textContent = "Sent.";
295	  } else if (out) {
296	    out.textContent = res.json && res.json.error ? res.json.error.message : "Not sent.";
297	  }
298	}
299	
300	// --- live updates: a WebSocket when the browser allows one, a poll when not
301	
302	function openSocket() {
303	  let ws;
304	  try {
305	    ws = new WebSocket("wss://" + location.host + "/api/v1/events");
306	  } catch {
307	    return;
308	  }
309	  let opened = false;
310	  state.socket = ws;
311	  ws.onopen = () => {
312	    opened = true;
313	    state.live = true;
314	    watch("watch");
315	    render();
316	  };
317	  ws.onmessage = (m) => {
318	    let ev;
319	    try {
320	      ev = JSON.parse(m.data);
321	    } catch {
322	      return;
323	    }
324	    if (ev.type === "resync_required") {
325	      refresh();
326	      return;
327	    }
328	    if (ev.type !== "changed" && ev.type !== "removed") return;
329	    const r = ev.resource || {};
330	    if (r.id === state.open && (r.kind === "conversation" || r.kind === "screen")) {
331	      loadContent().then(render);
332	    } else if (ev.revision > state.rev.projects) {
333	      refresh();
334	    }
335	  };
336	  ws.onclose = () => {
337	    if (state.socket === ws) state.socket = null;
338	    if (opened) {
339	      state.live = false;
340	      render();
341	    }
342	  };
343	  ws.onerror = () => {};
344	}
345	
346	function schedule() {
347	  clearInterval(state.timer);
348	  let since = 0;
349	  state.timer = setInterval(() => {
350	    since += POLL_MS;
351	    if (state.live) return;
352	    refresh();
353	    if (!state.socket && since >= RETRY_SOCKET_MS) {
354	      since = 0;
355	      openSocket();
356	    }
357	  }, POLL_MS);
358	}
359	
360	start();
361

