    /// The paired device behind a request's bearer token, seen now; or
    /// the refusal, which says nothing of the host.
    fn authenticate(&mut self, request: &RemoteRequest) -> Result<PairedDevice, RemoteReply> {
        // A browser holds its token in a cookie named for this host; a
        // cookie another host set is somebody else's and is ignored.
        let cookie_name = self
            .core
            .identity()
            .map(crate::core::remote::token_cookie_name);
        let cookie = cookie_name.as_ref().and_then(|name| {
            request
                .cookies
                .iter()
                .find(|(n, v)| n == name && !v.is_empty())
                .map(|(_, v)| v)
        });
        let Some(token) = request.bearer.as_ref().or(cookie) else {
            return Err(self.refuse(
                request,
                401,
                "unauthorized",
                "pair this device first",
                false,
            ));
        };
        let Some(device) = self
            .core
            .device_by_token(&remote::token_sha256(token))
            .cloned()
        else {
            let mut refused = self.refuse(
                request,
                401,
                "unauthorized",
                "the token is not known; pair again",
                false,
            );
            // Revoked, or made before a key rotation: have the browser
            // drop its own cookie so the page shows "pair again".
            if request.bearer.is_none()
                && let Some(name) = cookie_name
            {
                refused.headers.push(set_cookie(&name, "", Some(0)));
            }
            return Err(refused);
        };
        self.dispatch_inner(AppAction::DeviceSeen(device.id));
        Ok(device)
