/// A `Set-Cookie` header for a browser's token: unreadable by script,
/// never sent cross-site, and kept off the page files by its path.
/// `max_age` of `Some(0)` clears it.
fn set_cookie(name: &str, value: &str, max_age: Option<u32>) -> (String, String) {
    let age = max_age.map_or_else(String::new, |s| format!("; Max-Age={s}"));
