        "/app.js" => ("text/javascript; charset=utf-8", crate::web::APP_JS),
    /// the frame.
    fn error(status: u16, code: &str, message: &str) -> Self {
        Self {
            status,
            body: error_body(code, message),
            authenticated: false,
            headers: Vec::new(),
        }
    }
}

