/// A `Set-Cookie` header for a browser's token: unreadable by script,
/// never sent cross-site, and kept off the page files by its path.
fn token_cookie(name: &str, value: &str) -> (String, String) {
    (
        "Set-Cookie".to_owned(),
        format!("{name}={value}; Path=/api/v1/; Secure; HttpOnly; SameSite=Strict"),
    )
}

/// The `Set-Cookie` header that makes a browser drop the token cookie.
fn clearing_cookie(name: &str) -> (String, String) {
    (
        "Set-Cookie".to_owned(),
        format!("{name}=; Path=/api/v1/; Max-Age=0; Secure; HttpOnly; SameSite=Strict"),
    )
