// Revoked, or made before a key rotation: have the browser
// drop its own cookie so the page shows "pair again". The
// cookie is only consulted when no bearer came, so a refused
// bearer says nothing about the cookie and must not clear it.
if request.bearer.is_none()
    && let Some(name) = cookie_name
{
    refused.headers.push(clearing_cookie(&name));
}

